static uint64_t ns(void){struct timespec t;clock_gettime(CLOCK_MONOTONIC,&t);return (uint64_t)t.tv_sec*1000000000ull+t.tv_nsec;}
static const char *num(char b[32], double v){if(!isfinite(v))return "null";snprintf(b,32,"%.9g",v);for(char*p=b;*p;p++)if(*p==',')*p='.';return b;}
static void frame(unsigned long long seq){char n[4][32];debug_log_emit("{\"event\":\"frame\",\"render_seq\":%llu,\"dt_raw\":%s,\"dt_actual\":%s,\"game\":%d,\"in_menu\":%d,\"menu_screen\":%d,\"race_state\":%d,\"play_state\":%d,\"paused\":%d,\"movie\":%d,\"frozen\":%d,\"race_frames\":%d,\"race_total\":%s,\"race_time\":%s}",seq,num(n[0],(float)(1.0/60)),num(n[1],(float)(1.0/60)),1,0,7,2,1,0,0,0,(int)seq,num(n[2],(float)125.638),num(n[3],(float)(seq/60.0)));}
static void sim(unsigned long long seq,const char *phase){char n[25][32];double v[25]={.231234567,1,0,1234.12345,32.123456,-2325.321,23.123456,0.123456,-60.2356,1.234567,-0.0123456,0.024356,239.6512,7212.345,1234.567,35.8934,0,0,0,1234.543,32.4321,-2325.436,0.12345,0.98765,-0.123456};for(int i=0;i<25;i++)v[i]=(float)v[i];debug_log_emit("{\"event\":\"sim\",\"phase\":\"%s\",\"render_seq\":%llu,\"sim_seq\":%llu,\"step_index\":%d,\"steer\":%s,\"throttle\":%s,\"brake\":%s,\"shift_up\":%d,\"shift_down\":%d,\"analog\":%d,\"pos\":[%s,%s,%s],\"vel\":[%s,%s,%s],\"vel_valid\":%d,\"yaw\":%s,\"pitch\":%s,\"roll\":%s,\"speed\":%s,\"rpm\":%s,\"gear\":%d,\"area\":%d,\"next_area\":%d,\"section\":%d,\"remain_valid\":%d,\"remain\":%s,\"place\":%d,\"place_at\":%s,\"on_ground\":%d,\"wall_hit\":%s,\"impact\":%s,\"spark\":%s,\"spark_at\":[%s,%s,%s],\"spark_dir\":[%s,%s,%s],\"in_race\":%d,\"race_state\":%d,\"play_state\":%d}",phase,seq,seq,0,num(n[0],v[0]),num(n[1],v[1]),num(n[2],v[2]),0,0,1,num(n[3],v[3]),num(n[4],v[4]),num(n[5],v[5]),num(n[6],v[6]),num(n[7],v[7]),num(n[8],v[8]),1,num(n[9],v[9]),num(n[10],v[10]),num(n[11],v[11]),num(n[12],v[12]),num(n[13],v[13]),5,12,13,2,1,num(n[14],v[14]),2,num(n[15],v[15]),1,num(n[16],v[16]),num(n[17],v[17]),num(n[18],v[18]),num(n[19],v[19]),num(n[20],v[20]),num(n[21],v[21]),num(n[22],v[22]),num(n[23],v[23]),num(n[24],v[24]),1,2,1);}
int main(int argc,char**argv){if(argc!=2)return 2;int fd=open(argv[1],O_CREAT|O_EXCL|O_WRONLY,0600);if(fd<0){perror("open");return 3;}if(debug_log_start(fd))return 4;uint64_t sums[4]={0},max[4]={0},start=ns(),end=start+6000000000ull;unsigned long long frames=0;while(1){uint64_t deadline=start+frames*1000000000ull/60;uint64_t now=ns();if(deadline>=end)break;if(now<deadline){struct timespec d={(time_t)((deadline-now)/1000000000ull),(long)((deadline-now)%1000000000ull)};nanosleep(&d,0);}frames++;for(int j=0;j<4;j++){uint64_t a=ns();if(debug_log_enabled()){if(j==0)frame(frames);else if(j==1)sim(frames,"before");else if(j==2)sim(frames,"after");else debug_log_emit("{\"event\":\"present\",\"render_seq\":%llu,\"swap_us\":%llu}",frames,8333ull);}uint64_t dt=ns()-a;sums[j]+=dt;if(dt>max[j])max[j]=dt;}if(frames%120==0)debug_log_flush();}int failed=debug_log_failed();uint64_t t=ns();debug_log_close();uint64_t close=ns()-t;printf("frames=%llu attempted=%llu failed=%d close_ms=%.3f elapsed_ms=%.3f\n",frames,frames*4,failed,close/1e6,(ns()-start)/1e6);for(int j=0;j<4;j++)printf("kind=%s mean_us=%.3f max_us=%.3f\n",(const char*[]){"frame","before","after","present"}[j],sums[j]/(double)frames/1000,max[j]/1000.0);FILE *f=fopen(argv[1],"rb"); if(!f)return 6; char line[DEBUG_LOG_LINE_MAX]; unsigned long long events=0,gaps=0; while(fgets(line,sizeof line,f)){ if(strstr(line,"\"type\":\"event\""))events++; if(strstr(line,"\"type\":\"gap\""))gaps++; } fclose(f); printf("recorded=%llu gaps=%llu\n",events,gaps); if(failed || debug_log_failed())return 5; return (gaps || events!=frames*4)?7:0;}
